int dj_hid_raw_request(struct hid_device *hid, unsigned char reportnum, __u8 *buf, size_t count, unsigned char report_type, int reqtype) {
    int ret = 0;
    __u8 *outbuf = NULL;

    if (!hid || !buf || count == 0) {
        return -EINVAL;
    }

    if (count > HID_MAX_BUFFER_SIZE) {
        count = HID_MAX_BUFFER_SIZE;
    }

    outbuf = (__u8 *)malloc(count);
    if (!outbuf) {
        return -ENOMEM;
    }

    memcpy(outbuf, buf, count);

    ret = hid_hw_request(hid, outbuf, count, reportnum, report_type, reqtype);

    free(outbuf);
    return ret;
}
